#include "full_dive/chip_pipeline/NeuralChipOnlyFullDivePipeline.h"
#include <cassert>
int main(){ dnxr::NeuralChipBus bus; dnxr::NeuralChipOnlyFullDivePipeline p(bus); dnxr::NeuralChipOnlyWorldFrame w; w.frameId=1; w.timestampMs=1; assert(p.step(w)); assert(p.stateMachine().state()==dnxr::NeuralChipPipelineState::AwaitingAck); w.frameId=2; w.timestampMs=100; assert(!p.step(w)); assert(p.stateMachine().inHold()); p.emergencyLatch().trigger("stop"); w.frameId=3; w.timestampMs=101; assert(!p.step(w)); assert(p.stateMachine().emergencyLatched()); dnxr::EmergencyLatchResetRequest req{1,"op","reset",true,true}; assert(p.resetEmergencyLatchWithAudit(req)); assert(p.stateMachine().state()==dnxr::NeuralChipPipelineState::ControlledResume); dnxr::NeuralChipPipelineStateMachine sm; sm.start(); sm.shutdown(); assert(!sm.onResumeRampComplete()); assert(sm.state()==dnxr::NeuralChipPipelineState::Shutdown); }
